int shifts(List<int> a) {
  var s = 0;
  for (var i = 1; i < a.length; i++) {
    final cur = a[i];
    var j = i - 1;
    while (j >= 0 && a[j] > cur) {
      a[j + 1] = a[j];
      j--;
      s++;
    }
    a[j + 1] = cur;
  }
  return s;
}

void main() {
  print(shifts([1, 2, 4, 3, 5]));
  print(shifts([4, 3, 2, 1]));
}
