void sortBy<T>(List<T> a, int Function(T, T) cmp) {
  for (var i = 1; i < a.length; i++) {
    final cur = a[i];
    var j = i - 1;
    while (j >= 0 && cmp(a[j], cur) > 0) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = cur;
  }
}

void main() {
  final words = ['pear', 'fig', 'banana', 'kiwi'];
  sortBy<String>(words, (a, b) => a.length.compareTo(b.length));
  print(words);
}
